# Generated by new-portable-project.ps1 -Profile scripts.
# This is a self-contained portable Python workspace: scripts/ is a pinned copy
# of upstream tooling, python/ is generated, and your code lives in __APP_DIR__.
param (
  [string]$PythonVersion = "__PYTHON_VERSION__",
  [string]$VCRuntimeDir = "",
  [switch]$SkipInstall
)

$ErrorActionPreference = "Stop"

$Root = Split-Path -Parent $PSScriptRoot
$PythonExe = Join-Path $Root "python\python.exe"

if (-not (Test-Path (Join-Path $Root "scripts\bootstrap.ps1"))) {
  throw "Missing scripts\bootstrap.ps1. Re-run new-portable-project.ps1 -Profile scripts."
}

$NeedBootstrap = $true
if (Test-Path $PythonExe) {
  $Actual = (& $PythonExe -V).Trim() -replace '^Python\s+', ''
  $NeedBootstrap = $Actual -ne $PythonVersion
}
if ($NeedBootstrap) {
  & (Join-Path $Root "scripts\bootstrap.ps1") -Engine embeddable -Version $PythonVersion -NonInteractive
  if ($null -ne $LASTEXITCODE -and $LASTEXITCODE -ne 0) { throw "bootstrap.ps1 failed" }
}

if (-not $SkipInstall) {
  & (Join-Path $Root "scripts\pip.ps1") install -r (Join-Path $Root "__REQUIREMENTS__")
  if ($null -ne $LASTEXITCODE -and $LASTEXITCODE -ne 0) { throw "pip install failed" }
}

# Optional native runtime DLLs, if your scripts import MSVC-built extensions.
if ($VCRuntimeDir) {
  foreach ($Name in @("msvcp140.dll", "msvcp140_1.dll")) {
    $Source = Join-Path $VCRuntimeDir $Name
    if (Test-Path $Source) {
      Copy-Item $Source (Join-Path $Root "python\$Name") -Force
    }
    else {
      Write-Host "[WARN] $Name not found in $VCRuntimeDir" -ForegroundColor Yellow
    }
  }
}

# TODO: add a smoke test for your scripts, for example:
# & $PythonExe -m __MODULE__
# if ($LASTEXITCODE -ne 0) { throw "smoke test failed" }

@(
  "repo=https://github.com/ra9fael/python-portable-win",
  "commit=__UPSTREAM_COMMIT__",
  "python=$PythonVersion",
  "built=$((Get-Date).ToString('yyyy-MM-dd HH:mm'))"
) | Set-Content (Join-Path $Root "UPSTREAM.txt") -Encoding ASCII

& (Join-Path $Root "scripts\build_release.ps1")
if ($null -ne $LASTEXITCODE -and $LASTEXITCODE -ne 0) { throw "build_release.ps1 failed" }

Write-Host "`n[OK] Workspace: $Root" -ForegroundColor Green
Write-Host "     ZIP:       $(Join-Path $Root 'dist')" -ForegroundColor Green
